#include <iostream>

void swapInts(int& a, int& b)
{
    int temp{ a };
    a = b;
    b = temp;
}

int main()
{
    int a{};
    int b{};
    if (!(std::cin >> a >> b)) return 0;

    std::cout << "before " << a << ' ' << b << "\n";
    swapInts(a, b);
    std::cout << "after " << a << ' ' << b << "\n";

    return 0;
}
